from common_e15 import *
import numpy as np,pandas as pd
from reports_e15 import md

def main():
 out=[]
 for a in rows(R/'21_reproducibility/INTERVENTION_REGISTRY.csv'):
  if a['variant']!='OVERLAP' or a['condition']!='FULL':continue
  raw=dict(np.load(a['path']));loc=raw['core_position'];lo=np.full(34200,np.inf);hi=np.full(34200,-np.inf);np.minimum.at(lo,loc,raw['pred_MPa']);np.maximum.at(hi,loc,raw['pred_MPa']);diff=hi-lo;maximum=float(diff.max());assert maximum<=1e-4;out.append(dict(model=a['model'],fold=a['fold'],seed=a['seed'],source_id=a['source_id'],original_points=34200,multiple_raw_query_points=int(np.sum(np.bincount(loc,minlength=34200)>1)),maximum_same_input_regrouping_difference_MPa=maximum,tolerance_MPa=1e-4,passed=True))
 assert len(out)==52;table(R/'05_original_prediction_replay/FULL_QUERY_REGROUPING_INVARIANCE.csv',out)
 text='# Frozen SurfacePT dependency structure\n\nThe executed model is the SurfacePT.forward override in src/model_e3.py, not the base PointTransformerStress.forward implementation. For a query q and fixed geometry object G, it encodes the nineteen query features, aggregates three fixed sets of sixteen geometry-neighbor features, and concatenates a pooled context mean over the4096 geometry-selected input points. LayerNorm acts per query over channels. There is no query-to-query attention, batch normalization, query-batch pooling or dropout in this executed override.\n\nSchematic: h_q=encoder(f_q); local_q=multiscale_neighbor_attention(f_q,f_neighbor); global_G=mean(encoder(f_context)); output_q=out(LayerNorm(h_q+up([local_q,global_G]))). Consequently changing which other query points share a512-query batch at fixed G cannot create a mathematical dependence on those other queries. Floating-point matrix-shape effects are still checked numerically.\n\nThe common visible-centroid translation in the first three feature channels cancels in the positional difference f_q[:3]-f_neighbor[:3] at fixed neighbor identities. It does **not** cancel in the separate encoder inputs, including the context encoder; nor are the repeated visible-domain spans/normal statistics removed from those inputs. Thus source-global feature sensitivity is consistent with the actual dependency graph even though the positional subterm uses differences. The nine-channel oracle intervention does not identify individual learned weights, isolate centering from every global descriptor, or prove an internal attention mechanism.\n\nFULL OVERLAP reused identical full-view feature tensors, local neighborhoods and4096 selected context points while regrouping/repeating queries. All52 model/seed/source cases pass the1e-4MPa same-point tolerance; observed maximum is '+str(max(a['maximum_same_input_regrouping_difference_MPa'] for a in out))+'MPa. This supports separating actual restricted-view handoff discontinuities from arbitrary query batching. The old FULL reference lines remain internal diagnostic cuts, not original physical observation seams.\n\n'+md(pd.DataFrame(out).groupby('model')[['maximum_same_input_regrouping_difference_MPa']].max().reset_index())
 (R/'MODEL_DEPENDENCE_ALGEBRA.md').write_text(text,encoding='utf8')
 for name in ['R8E15_MASTER_REPORT.md','ORIGINAL_QUERY_TILE_GEOMETRY.md','NINETEEN_FEATURE_DEPENDENCY_AUDIT.md']:
  p=R/name;p.write_text(p.read_text(encoding='utf8')+'\n\n'+text,encoding='utf8')
 write(R/'18_independent_verification/ALGEBRA_AND_REGROUPING_PASS.json',dict(UTC=now(),passed=True,source_checkpoint_cases=len(out),maximum_regrouping_difference_MPa=max(a['maximum_same_input_regrouping_difference_MPa'] for a in out),new_inference_forwards=0));print('ALGEBRA_REGROUPING_PASS',max(a['maximum_same_input_regrouping_difference_MPa'] for a in out),flush=True)
if __name__=='__main__':main()
